.rpg-npc-avatar img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:2}
.rpg-npc-nm{font-size:12.5px;font-weight:700;color:var(--tx);flex:1;min-width:0}
.rpg-npc-rel{font-size:9px;font-weight:600;padding:2px 8px;border-radius:99px;white-space:nowrap}
.rpg-npc-bar-track{height:5px;border-radius:3px;background:var(--pan3);overflow:hidden;margin-bottom:6px}
.rpg-npc-bar-fill{height:100%;border-radius:3px;background:linear-gradient(90deg,var(--acc),rgba(var(--acc-rgb),.6))}
.rpg-npc-note{font-size:10.5px;color:var(--tx2);line-height:1.5}

/* RECORDS (Aetheric Records) */
#rpg-rec-toolbar{display:flex;gap:6px;margin-bottom:10px;padding:0 15px}
#rpg-rec-search{flex:1;background:var(--pan2);border:1px solid var(--bd2);border-radius:var(--r2);padding:6px 10px;color:var(--tx);font-size:11.5px;outline:none}
#rpg-rec-search:focus{border-color:var(--accb)}
#rpg-rec-filter{background:var(--pan2);border:1px solid var(--bd2);border-radius:var(--r2);padding:6px 8px;color:var(--tx2);font-size:11px;outline:none}
#rpg-rec-count{font-size:9.5px;color:var(--mu);padding:0 15px 8px}
#rpg-rec-list{padding:0 15px}
.rpg-rec-card{background:var(--pan2);border:1px solid var(--bd2);border-left:2px solid var(--acc);border-radius:0 var(--r2) var(--r2) 0;padding:9px 11px;margin-bottom:7px}
.rpg-rec-top{display:flex;align-items:center;gap:8px;margin-bottom:4px}
.rpg-rec-ttl{font-size:12px;font-weight:700;color:var(--tx);flex:1;min-width:0}
.rpg-rec-tag{font-size:8px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;padding:2px 7px;border-radius:99px;white-space:nowrap;flex-shrink:0}
.rpg-rec-desc{font-size:11px;color:var(--tx2);line-height:1.5}

/* MAP */
#rpg-map-wrap{position:relative;height:280px;background:radial-gradient(ellipse at 50% 40%,#141c2e 0%,#0a0e18 100%);overflow:hidden;touch-action:none;cursor:grab}
#rpg-map-wrap.grabbing{cursor:grabbing}
