.rpg-map-edge{stroke:rgba(201,146,42,.28);stroke-width:1.2;fill:none}
.rpg-map-node-dot{fill:#1a2338;stroke:var(--mu);stroke-width:1.4}
.rpg-map-node-dot.discovered{stroke:var(--acc);fill:#2a2010}
.rpg-map-node-dot.current{fill:var(--acc);stroke:#fff;stroke-width:1.6}
.rpg-map-node-lbl{font-size:6.5px;fill:#8a9ab0;font-family:'Inter',sans-serif;text-anchor:middle}
.rpg-map-node-lbl.discovered{fill:var(--tx2)}
.rpg-map-node-lbl.current{fill:var(--acc);font-weight:700}
#rpg-map-compass{position:absolute;top:10px;left:10px;width:30px;height:30px;opacity:.7;pointer-events:none}
#rpg-map-controls{position:absolute;top:10px;right:10px;display:flex;flex-direction:column;gap:5px}
.rpg-map-btn{width:26px;height:26px;border-radius:6px;background:rgba(20,25,40,.85);border:1px solid rgba(201,146,42,.3);color:var(--acc);display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;cursor:pointer;user-select:none;backdrop-filter:blur(3px)}
.rpg-map-btn:hover{background:rgba(201,146,42,.15)}
#rpg-map-current-lbl{position:absolute;bottom:10px;left:10px;font-size:10px;color:var(--tx2);background:rgba(20,25,40,.75);padding:4px 9px;border-radius:99px;border:1px solid var(--bd2)}

.rpg-empty{font-size:11.5px;color:var(--mu);font-style:italic;text-align:center;padding:20px 0}
#rpgfoot{padding:8px 15px;font-size:8.5px;letter-spacing:1.5px;text-transform:uppercase;color:var(--mu);text-align:center;border-top:1px solid var(--bd2);background:var(--pan)}
</style>
