<script>
(function(){
function g(id){return document.getElementById(id)}
function esc(v){if(v==null)return'';return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function pct(c,m){c=parseFloat(c);m=parseFloat(m);if(!(m>0))return 0;return Math.max(0,Math.min(100,Math.round(c/m*100)))}
function hexRgb(h){h=h||'#C9922A';try{return parseInt(h.slice(1,3),16)+','+parseInt(h.slice(3,5),16)+','+parseInt(h.slice(5,7),16)}catch(e){return '201,146,42'}}

var raw=g('rpgraw');var d=null;
if(raw&&raw.value.trim()){
  var dec=document.createElement('textarea');dec.innerHTML=raw.value.trim();
  try{d=JSON.parse(dec.value.trim())}catch(e){}
}
if(!d)d={};

var acc=d.charColor||'#C9922A';
var root=document.documentElement;
root.style.setProperty('--acc',acc);
var rgb=hexRgb(acc);
root.style.setProperty('--acc-rgb',rgb);
root.style.setProperty('--accd','rgba('+rgb+',.12)');
root.style.setProperty('--accb','rgba('+rgb+',.32)');

function riskColor(r){
  r=(r||'').toLowerCase();
  if(r==='low')return 'var(--safe)';
  if(r==='medium'||r==='moderate')return 'var(--warn)';
  if(r==='high'||r==='extreme')return 'var(--danger)';
  return 'var(--mu)';
}
function relColor(v){
  v=parseFloat(v)||0;
  if(v>=60)return 'var(--safe)';
  if(v>=30)return 'var(--warn)';
  return 'var(--danger)';
}
var TAG_COLORS={Economy:'var(--info)',NPC:'var(--warn)',Mystery:'#8A5FBF',War:'var(--danger)',Lore:'var(--acc)',Quest:'var(--safe)'};
function tagColor(t){return TAG_COLORS[t]||'var(--mu)'}

/* HEADER */
g('rpg-name').textContent=d.name||'Unnamed';
g('rpg-class').textContent=[d.class,d.race].filter(Boolean).join(' · ')+(d.level!=null?' · Lv '+d.level:'');
if(d.avatar){
  var img=document.createElement('img');
  img.src='https://files.catbox.moe/'+d.avatar;
  img.onerror=function(){this.style.display='none'};
  g('rpg-avatar').appendChild(img);
}
var cur=d.currency||{};
g('rpg-currency').textContent=(cur.label||'')+' '+(cur.amount!=null?cur.amount:0);
g('rpg-location-badge').textContent=d.location||'—';
var xp=d.xp||{cur:0,max:100};
g('rpg-xp-fill').style.width=pct(xp.cur,xp.max)+'%';
g('rpg-xp-txt').textContent='EXP '+esc(xp.cur)+'/'+esc(xp.max);
g('rpg-xp-lvl').textContent='Lv '+(d.level!=null?d.level:1);

/* OVERVIEW */
var ov=d.overview||{};
var idRows=[['Nickname',ov.nickname],['Language',ov.language],['Origin',ov.origin],['Race Detail',ov.raceDetail]];
g('ov-idgrid').innerHTML=idRows.map(function(r){return '<div class="rpg-icard"><div class="rpg-icard-l">'+esc(r[0])+'</div><div class="rpg-icard-v">'+esc(r[1]||'—')+'</div></div>';}).join('');
var stRows=[['MP Regen',ov.mpRegen],['Affiliation',ov.affiliation],['First Race',ov.firstRace],['Status',ov.status]];
g('ov-standing').innerHTML=stRows.map(function(r){return '<div class="rpg-icard"><div class="rpg-icard-l">'+esc(r[0])+'</div><div class="rpg-icard-v">'+esc(r[1]||'—')+'</div></div>';}).join('');

var mEl=g('ov-mission');
var mission=ov.mission;
if(mission&&mission.name){
  var rc=riskColor(mission.risk);
  mEl.innerHTML='<div class="rpg-mission-card">'+
    '<div class="rpg-mission-top"><span class="rpg-mission-nm">'+esc(mission.name)+'</span>'+
    (mission.risk?'<span class="rpg-risk" style="color:'+rc+';background:'+rc+'22;border:1px solid '+rc+'55">'+esc(mission.risk)+'</span>':'')+'</div>'+
    '<div class="rpg-prog-track"><div class="rpg-prog-fill" style="width:'+(mission.progress||0)+'%"></div></div>'+
    '<div class="rpg-mission-meta"><span>Progress '+(mission.progress||0)+'%</span><span>Followers: '+esc(mission.followers||'—')+'</span></div>'+
  '</div>';
}else{
  mEl.innerHTML='<div class="rpg-empty">No active objective.</div>';
}

/* WORLD */
var w=d.world||{};
var locRows=[['Location',w.location],['Area',w.area]];
g('w-locgrid').innerHTML=locRows.map(function(r){return '<div class="rpg-icard full"><div class="rpg-icard-l">'+esc(r[0])+'</div><div class="rpg-icard-v">'+esc(r[1]||'—')+'</div></div>';}).join('');
var timeRows=[['Day',w.day],['Time',w.time],['Season',w.season],['Weather',w.weather],['Year',w.year]];
g('w-timegrid').innerHTML=timeRows.map(function(r){return '<div class="rpg-icard"><div class="rpg-icard-l">'+esc(r[0])+'</div><div class="rpg-icard-v">'+esc(r[1]||'—')+'</div></div>';}).join('');
var noteEl=g('w-note-wrap');
noteEl.innerHTML=w.note?'<div class="rpg-sec mt">Notes</div><div class="rpg-note">'+esc(w.note)+'</div>':'';

/* RELATIONS */
var relEl=g('rel-list');
var npcs=d.npcs||[];
if(npcs.length){
  relEl.innerHTML=npcs.map(function(n){
    var col=relColor(n.closeness);
    var initial=(n.name||'?').trim().charAt(0).toUpperCase();
    var avatarInner=esc(initial)+(n.avatar?'<img src="https://files.catbox.moe/'+esc(n.avatar)+'" onerror="this.style.display=\'none\'">':'');
    return '<div class="rpg-npc-card">'+
      '<div class="rpg-npc-top"><div class="rpg-npc-avatar">'+avatarInner+'</div>'+
      '<div class="rpg-npc-nm">'+esc(n.name||'—')+'</div>'+
      (n.relation?'<span class="rpg-npc-rel" style="color:'+col+';background:'+col+'22;border:1px solid '+col+'55">'+esc(n.relation)+'</span>':'')+
      '</div>'+
      (n.closeness!=null?'<div class="rpg-npc-bar-track"><div class="rpg-npc-bar-fill" style="width:'+n.closeness+'%"></div></div>':'')+
      (n.note?'<div class="rpg-npc-note">'+esc(n.note)+'</div>':'')+
    '</div>';
  }).join('');
}else{
  relEl.innerHTML='<div class="rpg-empty">No NPCs recorded yet.</div>';
}

/* RECORDS (Aetheric Records) */
var records=d.records||[];
var recTags=[];
records.forEach(function(r){if(r.tag&&recTags.indexOf(r.tag)<0)recTags.push(r.tag)});
var filterEl=g('rpg-rec-filter');
recTags.forEach(function(t){
  var o=document.createElement('option');o.value=t;o.textContent=t;filterEl.appendChild(o);
});
var curSearch='',curFilter='';
function renderRecords(){
  var listEl=g('rpg-rec-list');
  var filtered=records.filter(function(r){
    var matchSearch=!curSearch||((r.title||'')+' '+(r.desc||'')).toLowerCase().indexOf(curSearch.toLowerCase())>=0;
    var matchFilter=!curFilter||r.tag===curFilter;
    return matchSearch&&matchFilter;
  });
  g('rpg-rec-count').textContent=filtered.length+' record'+(filtered.length===1?'':'s');
  if(filtered.length){
    listEl.innerHTML=filtered.map(function(r){
      var tc=tagColor(r.tag);
      return '<div class="rpg-rec-card">'+
        '<div class="rpg-rec-top"><span class="rpg-rec-ttl">'+esc(r.title||'—')+'</span>'+
        (r.tag?'<span class="rpg-rec-tag" style="color:'+tc+';background:'+tc+'22;border:1px solid '+tc+'55">'+esc(r.tag)+'</span>':'')+
        '</div>'+
        (r.desc?'<div class="rpg-rec-desc">'+esc(r.desc)+'</div>':'')+
      '</div>';
    }).join('');
  }else{
    listEl.innerHTML='<div class="rpg-empty">No records match.</div>';
  }
}
g('rpg-rec-search').addEventListener('input',function(){curSearch=this.value;renderRecords()});
