/* MAP */
var mapData=d.map||{};
var nodes=mapData.nodes||[];
var edges=mapData.edges||[];
var mapScale=1,mapTx=0,mapTy=0;
var svgG=g('rpg-map-g');

function nodeById(id){for(var i=0;i<nodes.length;i++){if(nodes[i].id===id)return nodes[i]}return null}

function renderMap(){
  if(!nodes.length){
    svgG.innerHTML='';
    g('rpg-map-current-lbl').textContent='No map data yet';
    return;
  }
  var vbW=300,vbH=280;
  var h='';
  edges.forEach(function(e){
    var a=nodeById(e[0]),b=nodeById(e[1]);
    if(!a||!b)return;
    var ax=(a.x/100)*vbW,ay=(a.y/100)*vbH,bx=(b.x/100)*vbW,by=(b.y/100)*vbH;
    h+='<line class="rpg-map-edge" x1="'+ax+'" y1="'+ay+'" x2="'+bx+'" y2="'+by+'"/>';
  });
  nodes.forEach(function(n){
    var nx=(n.x/100)*vbW,ny=(n.y/100)*vbH;
    var cls=n.current?'current':(n.discovered?'discovered':'');
    var label=n.discovered||n.current?(n.name||'—'):'???';
    h+='<circle class="rpg-map-node-dot '+cls+'" cx="'+nx+'" cy="'+ny+'" r="'+(n.current?5:3.6)+'"/>';
    h+='<text class="rpg-map-node-lbl '+cls+'" x="'+nx+'" y="'+(ny-8)+'">'+esc(label)+'</text>';
  });
  svgG.innerHTML=h;
  var cur=nodes.find(function(n){return n.current});
  g('rpg-map-current-lbl').textContent=cur?('At: '+(cur.name||cur.id)):'Location unknown';
  applyMapTransform();
}
function applyMapTransform(){
  svgG.setAttribute('transform','translate('+mapTx+','+mapTy+') scale('+mapScale+')');
}
function centerOnCurrent(){
  var cur=nodes.find(function(n){return n.current});
  mapScale=1;
  if(cur){
    mapTx=(150-(cur.x/100)*300)*1;
    mapTy=(140-(cur.y/100)*280)*1;
  }else{
    mapTx=0;mapTy=0;
  }
  applyMapTransform();
}
g('map-zoom-in').addEventListener('click',function(){mapScale=Math.min(3,mapScale+.25);applyMapTransform()});
g('map-zoom-out').addEventListener('click',function(){mapScale=Math.max(.4,mapScale-.25);applyMapTransform()});
g('map-center').addEventListener('click',centerOnCurrent);

var mapWrap=g('rpg-map-wrap');
var dragging=false,dragStartX,dragStartY,dragOrigTx,dragOrigTy;
function mapDown(x,y){dragging=true;dragStartX=x;dragStartY=y;dragOrigTx=mapTx;dragOrigTy=mapTy;mapWrap.classList.add('grabbing')}
function mapMove(x,y){if(!dragging)return;mapTx=dragOrigTx+(x-dragStartX);mapTy=dragOrigTy+(y-dragStartY);applyMapTransform()}
function mapUp(){dragging=false;mapWrap.classList.remove('grabbing')}
mapWrap.addEventListener('mousedown',function(e){mapDown(e.clientX,e.clientY)});
window.addEventListener('mousemove',function(e){mapMove(e.clientX,e.clientY)});
window.addEventListener('mouseup',mapUp);
mapWrap.addEventListener('touchstart',function(e){var t=e.touches[0];mapDown(t.clientX,t.clientY)},{passive:true});
mapWrap.addEventListener('touchmove',function(e){var t=e.touches[0];mapMove(t.clientX,t.clientY)},{passive:true});
mapWrap.addEventListener('touchend',mapUp);
mapWrap.addEventListener('wheel',function(e){
  e.preventDefault();
  mapScale=Math.max(.4,Math.min(3,mapScale+(e.deltaY<0?.15:-.15)));
  applyMapTransform();
},{passive:false});

renderMap();
centerOnCurrent();

